// Chọn chủ đề tự động theo khung giờ hoặc ngẫu nhiên
const now = new Date();
const hour = now.getHours();

// Danh mục Bách khoa gỗ quý toàn cầu
const worldWoods = [
  { topic: "Gỗ Tử Đàn Tiểu Diệp Ấn Độ: Vì sao hạt chìm nước và cách nhận biết phôi già mộc thật", wood: "Tử Đàn", category: "kien-thuc-ve-go" },
  { topic: "Gỗ Sưa Đỏ Bắc Bộ: Bí mật vân mây biến ảo và bài học phân biệt sưa Hải Nam", wood: "Sưa Đỏ", category: "kien-thuc-ve-go" },
  { topic: "Nu Bách Xanh Mộc Châu: Hương thơm ngọt ngào và dòng nu chớp quý hiếm", wood: "Bách Xanh", category: "kien-thuc-ve-go" },
  { topic: "Gỗ Hoàng Đàn Tuyết Lạng Sơn: Lớp tuyết ngọc tự nhiên và giá trị quà biếu lãnh đạo", wood: "Hoàng Đàn", category: "kien-thuc-ve-go" },
  { topic: "Gỗ Trắc Dây và Trắc Đỏ Đen: Đẳng cấp tôm gỗ đanh thép vượt thời gian", wood: "Gỗ Trắc", category: "kien-thuc-ve-go" },
  { topic: "Mun Sừng Khánh Hòa: Sắc đen huyền bí như đá ngọc và cách lên nước bóng mộc", wood: "Mun Sừng", category: "kien-thuc-ve-go" }
];

// Danh mục Phong thủy Ngũ Hành
const fengShuiTopics = [
  { topic: "Người Mệnh Kim Đeo Vòng Gỗ Gì? Quy tắc tương sinh Thổ sinh Kim và chất gỗ đắc lộc", element: "Kim", category: "huong-dan-lua-chon" },
  { topic: "Người Mệnh Mộc Hợp Vòng Gỗ Nào? Bí quyết chọn chất gỗ tịnh tâm, vững vàng sự nghiệp", element: "Mộc", category: "huong-dan-lua-chon" },
  { topic: "Mệnh Thủy Đeo Gỗ Màu Gì Hút Vượng Khí? Tử đàn, Mun sừng hay Trắc đen cổ thụ?", element: "Thủy", category: "huong-dan-lua-chon" },
  { topic: "Mệnh Hỏa Nên Chọn Vòng Tay Gỗ Nào? Cách kích hoạt năng lượng hưng vượng bình an", element: "Hỏa", category: "huong-dan-lua-chon" },
  { topic: "Người Mệnh Thổ và Duyên Gỗ Quý: Những loại danh mộc bổ trợ bản mệnh tài lộc", element: "Thổ", category: "huong-dan-lua-chon" }
];

let selected;
if (hour >= 6 && hour < 10) {
  // Ca 1: Sáng sớm - Kiến thức gỗ
  selected = worldWoods[Math.floor(Math.random() * worldWoods.length)];
} else {
  // Ca 2 & 3: Trưa & Tối - Phong thủy ngũ hành
  selected = fengShuiTopics[Math.floor(Math.random() * fengShuiTopics.length)];
}

return {
  topic: selected.topic,
  category: selected.category,
  keyword: selected.wood || selected.element,
  timestamp: new Date().toISOString()
};

// Parse kết quả JSON từ Agent 1
const rawText = $json.text || $json.response || "";
let cleanJson = rawText.trim();

if (cleanJson.startsWith("```json")) {
  cleanJson = cleanJson.replace(/```json\n?/, "").replace(/\n?```$/, "");
} else if (cleanJson.startsWith("```")) {
  cleanJson = cleanJson.replace(/```\n?/, "").replace(/\n?```$/, "");
}

let parsed;
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    title: $node["Chọn Chủ Đề Theo Ca"].json.topic,
    slug: "bai-viet-" + Date.now(),
    excerpt: "Cẩm nang chia sẻ kiến thức gỗ quý và phong thủy ngũ hành từ xưởng Mỹ Nghệ Đông Phong.",
    tags: ["Gỗ quý", "Phong thủy"],
    content_html: rawText
  };
}

// Chuẩn bị payload chuẩn cho bảng posts Supabase
const postId = "post_" + Date.now();
const category = $node["Chọn Chủ Đề Theo Ca"].json.category || "kien-thuc-ve-go";

return {
  id: postId,
  title: parsed.title,
  slug: parsed.slug || ("post-" + Date.now()),
  excerpt: parsed.excerpt,
  content: parsed.content_html,
  category: category,
  author_name: "Nghệ nhân Đông Phong",
  read_time: 6,
  status: "published",
  tags: parsed.tags || [],
  thumbnail: "https://images.unsplash.com/photo-1546484396-fb3fc6f95f98?auto=format&fit=crop&w=1200&q=80",
  published_at: new Date().toISOString()
};

